import 'package:flutter/material.dart';import 'package:flutter/services.dart';import '../../../core/network/api_endpoints.dart';import '../../../core/network/dio_client.dart';import '../../../shared/widgets/app_card.dart';
class ConfigScriptPage extends StatefulWidget{const ConfigScriptPage({super.key});@override State<ConfigScriptPage> createState()=>_S();}class _S extends State<ConfigScriptPage>{final c=TextEditingController();String saved='';bool busy=true;@override void initState(){super.initState();load();}Future<void>load()async{final r=await DioClient.instance.dio.get(ApiEndpoints.configScript);final d=r.data as Map;if(mounted)setState((){saved=d['content']?.toString()??'';c.text=saved;busy=false;});}Future<void>save()async{await DioClient.instance.dio.put(ApiEndpoints.configScript,data:{'content':c.text});if(mounted)setState(()=>saved=c.text);}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext x)=>Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('高级配置脚本'),actions:[IconButton(onPressed:()=>Clipboard.setData(ClipboardData(text:c.text)),icon:const Icon(Icons.copy)),IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:busy?const Center(child:CircularProgressIndicator()):Padding(padding:const EdgeInsets.all(20),child:Column(children:[Expanded(child:AppCard(child:TextField(controller:c,maxLines:null,expands:true,style:const TextStyle(fontFamily:'monospace'),decoration:const InputDecoration(border:InputBorder.none)))),const SizedBox(height:12),AppLiquidGlassButton(label:c.text==saved?'已保存':'保存配置',onPressed:c.text==saved?null:save)])));}
